List<WeatherLocationDraft> searchChinaCityDivisions(String query, {int limit = 20}) {
  final clean = query.trim();
  if (clean.length < 2) return const [];

  final normalizedQuery = clean.replaceAll(RegExp(r'(特别行政区|自治州|地区|盟|自治县|区|县|市|省)$'), '');
  final effectiveQuery = normalizedQuery.isNotEmpty ? normalizedQuery : clean;

  final exactMatches = <ChinaCityDivision>[];
  final prefixMatches = <ChinaCityDivision>[];
  final fuzzyMatches = <ChinaCityDivision>[];

  for (final div in kChinaCityDivisions) {
    final divNorm = div.name.replaceAll(RegExp(r'(特别行政区|自治州|地区|盟|自治县|区|县|市|省)$'), '');
    final effectiveDiv = divNorm.isNotEmpty ? divNorm : div.name;

    if (div.name == clean || effectiveDiv == effectiveQuery) {
      exactMatches.add(div);
    } else if (div.name.startsWith(clean) || effectiveDiv.startsWith(effectiveQuery)) {
      prefixMatches.add(div);
    } else if (div.name.contains(clean) ||
               effectiveDiv.contains(effectiveQuery) ||
               div.province.contains(clean) ||
               div.city.contains(clean)) {
      fuzzyMatches.add(div);
    }
  }

  final results = <ChinaCityDivision>[
    ...exactMatches,
    ...prefixMatches,
    ...fuzzyMatches,
  ];

  final uniqueDrafts = <String, WeatherLocationDraft>{};
  for (final div in results) {
    final draft = div.toDraft();
    final key = '${draft.admin1}_${draft.admin2}_${draft.name}';
    if (!uniqueDrafts.containsKey(key)) {
      uniqueDrafts[key] = draft;
      if (uniqueDrafts.length >= limit) break;
    }
  }

  return uniqueDrafts.values.toList();
}
